\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
	\lean{MIPStarRE.QPBT.PolyIndex, MIPStarRE.QPBT.PolyMeas, MIPStarRE.QPBT.PolyMeasFamily, MIPStarRE.QPBT.PolyMeasTuple}
	\leanok
